from __future__ import annotations

import dataclasses
import typing as t

import pytest
from commitizen import git

from cz_version_bump.thanks import Thanker

if t.TYPE_CHECKING:
    from pytest_httpserver import HTTPServer


@pytest.fixture(autouse=True)
def _env(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setenv("INPUT_GITHUB_TOKEN", "my_gh_token")


@dataclasses.dataclass
class DummyAuthor:
    id: int
    login: str
    path: str
    type: str


@pytest.mark.parametrize(
    "author,expected",
    [
        pytest.param(
            DummyAuthor(101, "jappleseed", "users/j.appleseed", "User"),
            " -- _**Thanks @jappleseed!**_",
            id="third_party_contributor",
        ),
        pytest.param(
            DummyAuthor(1, "user1", "users/user1", "User"),
            "",
            id="org_member",
        ),
        pytest.param(
            DummyAuthor(2, "dependabot[bot]", "users/dependabot[bot]", "Bot"),
            "",
            id="bot",
        ),
    ],
)
def test_thanker(httpserver: HTTPServer, author: DummyAuthor, expected: str) -> None:
    org = "my_gh_org"
    repo = "my_gh_repo"
    base_url = httpserver.url_for("/")

    httpserver.expect_request(f"/repos/{org}/{repo}").respond_with_json(
        {
            "id": 12,
            "name": repo,
            "organization": {"id": 34, "login": org},
            "url": f"{base_url}repos/{org}/{repo}",
        },
    )

    httpserver.expect_request(f"/orgs/{org}").respond_with_json(
        {
            "id": 34,
            "login": org,
            "url": f"{base_url}orgs/{org}",
        },
    )

    httpserver.expect_request(f"/orgs/{org}/members").respond_with_json(
        [
            {"id": 1, "login": "user1"},
            {"id": 2, "login": "user2"},
            {"id": 3, "login": "user3"},
        ]
    )

    sha = "abc123"
    title = "chore: I am a commit title"
    commit = git.GitCommit(sha, title)

    httpserver.expect_request(
        f"/repos/{org}/{repo}/commits/{commit.rev}"
    ).respond_with_json(
        {
            "sha": commit.rev,
            "commit": {
                "author": {
                    "name": "Johnny Appleseed",
                    "email": "j.appleseed@example.com",
                    "date": "2021-01-01T00:00:00Z",
                },
            },
            "author": {
                "id": author.id,
                "login": author.login,
                "url": f"{base_url}{author.path}",
                "type": author.type,
            },
        },
    )

    thanker = Thanker(f"{org}/{repo}", base_url=base_url)
    assert thanker.thanks_message(commit) == expected

"""Utility to automatically highlight third-party contributions in the changelog."""

from __future__ import annotations

import os
import re
import typing as t
from warnings import warn

from github import Auth, Consts, Github, NamedUser

if t.TYPE_CHECKING:
    from collections.abc import Iterable

    from commitizen import git


class Thanker:
    co_author_pattern = re.compile(r"<(.*)>$")

    def __init__(
        self: Thanker,
        repo_name: str,
        base_url: str = Consts.DEFAULT_BASE_URL,
    ) -> None:
        github_token = [REDACTED]
            "INPUT_GITHUB_TOKEN", os.environ.get("GITHUB_TOKEN", None)
        )
        if github_token is None:
            warn(
                "No GitHub token provided - changelog may include "
                "thanks for first-party contributors",
                stacklevel=2,
            )
            auth = None
        else:
            auth = Auth.Token(github_token)

        self.agent = Github(auth=auth, base_url=base_url)
        self.repo = self.agent.get_repo(repo_name)
        # NOTE: The org object obtained from `self.repo.organization` has the wrong URL,
        # so we retrieve it using `get_organization` instead to get one that isn't
        # broken.
        self.org = self.agent.get_organization(self.repo.organization.login)
        self.org_members = {member.login for member in self.org.get_members()}

    def thanks_message(self, commit: git.GitCommit) -> str:
        usernames = [
            f"@{username}" for username in self.third_party_contributors(commit)
        ]
        if not usernames:
            return ""
        template = " -- _**Thanks {}!**_"
        if len(usernames) == 1:
            return template.format(usernames[0])
        return template.format(f"{', '.join(usernames[:-1])}, and {usernames[-1]}")

    def third_party_contributors(self: Thanker, commit: git.GitCommit) -> Iterable[str]:
        for contributor in self.contributors(commit):
            # Exclude org members and dependabot from the thanks message
            if contributor.login not in self.org_members and contributor.type != "Bot":
                yield contributor.login

    def contributors(
        self: Thanker,
        commit: git.GitCommit,
    ) -> Iterable[NamedUser.NamedUser]:
        github_commit = self.repo.get_commit(commit.rev)
        yield github_commit.author
        # FIXME: Cannot thank co-authors automatically until `email_to_github_username`
        # is implemented.
        # yield from self.co_authors(github_commit.commit.message)  # noqa: ERA001

    def co_authors(self: Thanker, commit_message: str) -> Iterable[str]:
        co_author_lines = {
            line
            for line in commit_message.splitlines()
            if line.startswith("Co-authored-by: ")
        }
        for line in co_author_lines:
            if match := self.co_author_pattern.search(line):
                yield self.email_to_github_username(match.group(1))

    # TODO: This method should use memoization - https://pypi.org/project/methodtools/
    def email_to_github_username(self: Thanker, email: str) -> str:
        # TODO: Find a reliable way to get the GitHub username linked to a given email
        # address.
        # The user search API was tried, but it cannot find many users given their
        # public primary GitHub emails. I'm not sure why it is not reliable, or what
        # conditions make it work.
        raise NotImplementedError
